CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,full_name TEXT NOT NULL,email TEXT UNIQUE COLLATE NOCASE NOT NULL,phone TEXT NOT NULL,username TEXT UNIQUE COLLATE NOCASE NOT NULL,role TEXT NOT NULL,password_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS aircraft(id INTEGER PRIMARY KEY,registration TEXT UNIQUE NOT NULL,type TEXT NOT NULL,rows INTEGER NOT NULL CHECK(rows BETWEEN 4 AND 50),empty_kg REAL NOT NULL,max_takeoff_kg REAL NOT NULL,airworthy INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS flights(id INTEGER PRIMARY KEY,number TEXT UNIQUE COLLATE NOCASE NOT NULL,origin TEXT NOT NULL,destination TEXT NOT NULL,departure INTEGER NOT NULL,arrival INTEGER NOT NULL,delay_minutes INTEGER NOT NULL DEFAULT 0,price_cents INTEGER NOT NULL,aircraft_id INTEGER NOT NULL REFERENCES aircraft(id),gate TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'SCHEDULED',preflight INTEGER NOT NULL DEFAULT 0,weight_checked INTEGER NOT NULL DEFAULT 0,pushback INTEGER NOT NULL DEFAULT 0,cargo_kg REAL NOT NULL DEFAULT 0,fuel_kg REAL NOT NULL DEFAULT 3000,emergency INTEGER NOT NULL DEFAULT 0,callsign TEXT NOT NULL DEFAULT '',icao24 TEXT NOT NULL DEFAULT '',CHECK(origin<>destination),CHECK(arrival>departure),CHECK(price_cents>0));
CREATE TABLE IF NOT EXISTS crew(id INTEGER PRIMARY KEY,name TEXT NOT NULL,duty TEXT NOT NULL,certified_until INTEGER NOT NULL,aircraft_type TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS flight_crew(flight_id INTEGER NOT NULL REFERENCES flights(id),crew_id INTEGER NOT NULL REFERENCES crew(id),PRIMARY KEY(flight_id,crew_id));
CREATE TABLE IF NOT EXISTS bookings(reference TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),flight_id INTEGER NOT NULL REFERENCES flights(id),passenger_name TEXT NOT NULL,passport TEXT NOT NULL,date_of_birth TEXT NOT NULL,guardian_reference TEXT NOT NULL DEFAULT '',guardian_name TEXT NOT NULL DEFAULT '',guardian_phone TEXT NOT NULL DEFAULT '',seat TEXT NOT NULL,fare_class TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'CONFIRMED',paid_cents INTEGER NOT NULL,baggage_pieces INTEGER NOT NULL DEFAULT 0,baggage_kg REAL NOT NULL DEFAULT 0,baggage_fee_cents INTEGER NOT NULL DEFAULT 0,identity_verified INTEGER NOT NULL DEFAULT 0,passenger_screen TEXT NOT NULL DEFAULT 'PENDING',baggage_screen TEXT NOT NULL DEFAULT 'PENDING',gate_cleared INTEGER NOT NULL DEFAULT 0,assistance TEXT NOT NULL DEFAULT 'None',meal TEXT NOT NULL DEFAULT 'Standard',refund_cents INTEGER NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX IF NOT EXISTS active_seat ON bookings(flight_id,seat) WHERE status<>'CANCELLED';
CREATE UNIQUE INDEX IF NOT EXISTS active_identity ON bookings(flight_id,passport) WHERE status<>'CANCELLED';
CREATE TABLE IF NOT EXISTS ground_tasks(id INTEGER PRIMARY KEY,flight_id INTEGER NOT NULL REFERENCES flights(id),name TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'NOT_STARTED',assigned_team TEXT NOT NULL DEFAULT 'Ground Team A',UNIQUE(flight_id,name));
CREATE TABLE IF NOT EXISTS counters(counter TEXT PRIMARY KEY,session_token TEXT NOT NULL,user_id INTEGER NOT NULL REFERENCES users(id),flight_id INTEGER NOT NULL REFERENCES flights(id),expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS runway_slots(id INTEGER PRIMARY KEY,flight_id INTEGER UNIQUE NOT NULL REFERENCES flights(id),runway TEXT NOT NULL DEFAULT '',start_time INTEGER NOT NULL DEFAULT 0,end_time INTEGER NOT NULL DEFAULT 0,operation TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'QUEUED',queued_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),created_at INTEGER NOT NULL,message TEXT NOT NULL,is_read INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,created_at INTEGER NOT NULL,actor TEXT NOT NULL,action TEXT NOT NULL,details TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS watchlist(name TEXT PRIMARY KEY,reason TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS incidents(id INTEGER PRIMARY KEY,flight_id INTEGER NOT NULL REFERENCES flights(id),category TEXT NOT NULL,reason TEXT NOT NULL,location TEXT NOT NULL,happened_at INTEGER NOT NULL,description TEXT NOT NULL,severity TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'OPEN',reporter TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS maintenance_log(id INTEGER PRIMARY KEY,aircraft_id INTEGER NOT NULL REFERENCES aircraft(id),created_at INTEGER NOT NULL,inspector TEXT NOT NULL,result TEXT NOT NULL,notes TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS claims(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),reference TEXT NOT NULL REFERENCES bookings(reference),description TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'OPEN');
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
INSERT OR IGNORE INTO settings VALUES('weather','CLEAR');
CREATE TABLE IF NOT EXISTS demo_batches(id INTEGER PRIMARY KEY,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS demo_flights(flight_id INTEGER PRIMARY KEY REFERENCES flights(id),batch_id INTEGER NOT NULL REFERENCES demo_batches(id));
